/**
 * Yugipedia integration.
 *
 * Yugipedia is the community wiki that carries what the official databases do
 * not: per-card Gallery / Rulings / Errata / Artworks / Tips / Trivia /
 * Appearances / Names / Lores pages, the Yu-Gi-Oh! Card Database ID, every
 * language name, plus set, product and archetype articles.
 *
 * Why rendered HTML instead of raw wikitext: most of a card page's sections
 * ("TCG sets", "Other languages", "Search categories") are generated by
 * templates, so they do not exist as `== headings ==` in the source. The parse
 * API's rendered text is the only faithful view.
 *
 * Etiquette: descriptive User-Agent, one request at a time with 250 ms spacing,
 * 7-day local cache, 429 back-off. Content is CC BY-SA 3.0; every result carries
 * its source URL and licence.
 */

import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, "..", "..", "..");
const CACHE_DIR = path.join(ROOT, "data", "wiki");
const PAGE_CACHE = path.join(CACHE_DIR, "pages");

const API = "https://yugipedia.com/api.php";
const USER_AGENT = "yugioh-assistant-mcp/1.2 (Yu-Gi-Oh! card assistant; contact: local user)";
const MIN_INTERVAL_MS = 250;
const TTL_MS = 7 * 24 * 60 * 60 * 1000;
const MAX_TEXT = 8000;

export const YUGIPEDIA_LICENSE = "CC BY-SA 3.0";
export const YUGIPEDIA_API = API;

/** Namespaced pages that back the tabs on a card page. */
export const CARD_TABS = {
  gallery: "Card Gallery",
  rulings: "Card Rulings",
  errata: "Card Errata",
  artworks: "Card Artworks",
  tips: "Card Tips",
  trivia: "Card Trivia",
  appearances: "Card Appearances",
  names: "Card Names",
  lores: "Card Lores"
} as const;

export type CardTab = keyof typeof CARD_TABS;

interface CachedPage {
  title: string;
  html: string;
  wikitext: string;
  sections: Array<{ index: string; line: string; level: string }>;
  fetchedAt: string;
  /** Extracted once at write time: galleries are ~900 KB of HTML per page. */
  images?: string[];
}

// ---------------------------------------------------------------------------
// Transport
// ---------------------------------------------------------------------------

let lastRequestAt = 0;
let queue: Promise<unknown> = Promise.resolve();

const sleep = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

function serialize<T>(task: () => Promise<T>): Promise<T> {
  const run = queue.then(async () => {
    const wait = MIN_INTERVAL_MS - (Date.now() - lastRequestAt);
    if (wait > 0) await sleep(wait);
    lastRequestAt = Date.now();
    return task();
  });
  queue = run.then(() => undefined, () => undefined);
  return run;
}

async function apiRequest(params: Record<string, string>, attempt = 0): Promise<any> {
  const url = `${API}?${new URLSearchParams({ format: "json", formatversion: "2", ...params })}`;
  const response = await fetch(url, {
    headers: { "User-Agent": USER_AGENT, Accept: "application/json" },
    signal: AbortSignal.timeout(45_000)
  });

  if (response.status === 429 || response.status === 503) {
    if (attempt < 2) {
      await sleep(1500 * (attempt + 1));
      return apiRequest(params, attempt + 1);
    }
    throw new Error(`Yugipedia is rate limiting (HTTP ${response.status}). Try again later.`);
  }
  if (!response.ok) throw new Error(`Yugipedia returned HTTP ${response.status}`);
  return await response.json();
}

const callApi = <T = any>(params: Record<string, string>): Promise<T> => serialize(() => apiRequest(params)) as Promise<T>;

const cacheKey = (title: string) => crypto.createHash("sha1").update(title).digest("hex");

function readCache(title: string): CachedPage | null {
  try {
    const file = path.join(PAGE_CACHE, `${cacheKey(title)}.json`);
    if (!fs.existsSync(file)) return null;
    const parsed = JSON.parse(fs.readFileSync(file, "utf-8")) as CachedPage;
    if (Date.now() - new Date(parsed.fetchedAt).getTime() > TTL_MS) return null;
    return parsed;
  } catch {
    return null;
  }
}

function writeCache(page: CachedPage): void {
  fs.mkdirSync(PAGE_CACHE, { recursive: true });
  fs.writeFileSync(path.join(PAGE_CACHE, `${cacheKey(page.title)}.json`), JSON.stringify(page), "utf-8");
}

// ---------------------------------------------------------------------------
// HTML → text
// ---------------------------------------------------------------------------

function decodeEntities(input: string): string {
  const named: Record<string, string> = {
    amp: "&", lt: "<", gt: ">", quot: '"', apos: "'", nbsp: " ",
    ldquo: "“", rdquo: "”", lsquo: "‘", rsquo: "’", ndash: "–", mdash: "—",
    hellip: "…", bull: "•", middot: "·", times: "×", deg: "°"
  };
  return input
    .replace(/&#(\d+);/g, (_m, d) => String.fromCodePoint(Number(d)))
    .replace(/&#x([0-9a-f]+);/gi, (_m, h) => String.fromCodePoint(parseInt(h, 16)))
    .replace(/&([a-z]+);/gi, (m, name) => named[name.toLowerCase()] ?? m);
}

/** Index just past the matching close tag for `tag` starting at `start`. */
function findElementEnd(html: string, start: number, tag: string): number {
  const openRe = new RegExp(`<${tag}\\b`, "gi");
  const closeRe = new RegExp(`</${tag}>`, "gi");
  let depth = 0;
  let i = start;
  while (i < html.length) {
    openRe.lastIndex = i;
    closeRe.lastIndex = i;
    const open = openRe.exec(html);
    const close = closeRe.exec(html);
    if (!close) return -1;
    if (open && open.index < close.index) {
      depth++;
      i = open.index + open[0].length;
    } else {
      depth--;
      i = close.index + close[0].length;
      if (depth === 0) return i;
    }
  }
  return -1;
}

/**
 * Removes wiki furniture (tab bars, navboxes, maintenance banners) that would
 * otherwise drown the actual rulings/trivia text.
 */
export function stripWikiChrome(html: string): string {
  let out = html;
  const needles = ["mobile-show", "navbox-wrapper", "navbox", "ambox", "mbox-small", "hatnote", "metadata", "mw-editsection"];
  for (const needle of needles) {
    let index = 0;
    for (let guard = 0; guard < 200; guard++) {
      const re = new RegExp(`<(div|table|span|tr|td)[^>]*class="[^"]*${needle}[^"]*"[^>]*>`, "i");
      const rest = out.slice(index);
      const m = re.exec(rest);
      if (!m) break;
      const start = index + (m.index as number);
      const end = findElementEnd(out, start, m[1].toLowerCase());
      if (end < 0) {
        index = start + m[0].length;
        continue;
      }
      out = out.slice(0, start) + out.slice(end);
      index = start;
    }
  }
  return out;
}

export function htmlToText(html: string): string {
  let text = html;
  text = stripWikiChrome(text);
  text = text.replace(/<script[\s\S]*?<\/script>/gi, " ");
  text = text.replace(/<style[\s\S]*?<\/style>/gi, " ");
  text = text.replace(/<sup[^>]*class="[^"]*reference[^"]*"[\s\S]*?<\/sup>/gi, " ");
  text = text.replace(/<div[^>]*id="toc"[^>]*>[\s\S]*?<\/div>/gi, " ");
  text = text.replace(/<table[\s\S]*?<\/table>/gi, (table) => htmlTableToText(table));
  text = text.replace(/<li[^>]*>/gi, "\n• ");
  text = text.replace(/<\/(p|div|li|tr|h[1-6]|dd|dt)>/gi, "\n");
  text = text.replace(/<br\s*\/?>/gi, "\n");
  text = text.replace(/<[^>]+>/g, " ");
  text = decodeEntities(text);
  return text
    .split("\n")
    .map((line) => line.replace(/[ \t]+/g, " ").trim())
    .filter((line, i, arr) => line.length > 0 || (i > 0 && arr[i - 1].length > 0))
    .join("\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

function htmlTableToText(table: string): string {  const rows = [...table.matchAll(/<tr[^>]*>([\s\S]*?)<\/tr>/gi)];
  const lines: string[] = [];
  for (const row of rows) {
    const cells = [...row[1].matchAll(/<t[hd][^>]*>([\s\S]*?)<\/t[hd]>/gi)].map((c) =>
      decodeEntities(c[1].replace(/<[^>]+>/g, " ")).replace(/\s+/g, " ").trim()
    );
    const line = cells.filter(Boolean).join(" | ");
    if (line) lines.push(line);
  }
  return lines.length ? `\n${lines.join("\n")}\n` : " ";
}

interface RenderedSection {
  title: string;
  level: number;
  text: string;
}

/** Splits rendered article HTML on its h2/h3/h4 headings. */
export function splitHtmlSections(html: string): RenderedSection[] {
  const cleaned = stripWikiChrome(html);
  const articleMatch = cleaned.match(/<div[^>]*class="[^"]*mw-parser-output[^"]*"[^>]*>/i);
  const body = articleMatch && articleMatch.index !== undefined ? cleaned.slice(articleMatch.index) : cleaned;

  const headingRe = /<h([2-4])[^>]*>([\s\S]*?)<\/h\1>/gi;
  const marks: Array<{ index: number; title: string; level: number; end: number }> = [];
  for (const m of body.matchAll(headingRe)) {
    const title = decodeEntities(m[2].replace(/<[^>]+>/g, " ")).replace(/\s+/g, " ").trim();
    if (!title || /^contents$/i.test(title)) continue;
    marks.push({ index: m.index as number, title, level: Number(m[1]), end: (m.index as number) + m[0].length });
  }

  const sections: RenderedSection[] = [];
  if (marks.length === 0) {
    return [{ title: "Lead", level: 0, text: htmlToText(body) }];
  }

  const lead = htmlToText(body.slice(0, marks[0].index));
  if (lead.length > 0) sections.push({ title: "Lead", level: 0, text: lead });

  marks.forEach((mark, i) => {
    const end = i + 1 < marks.length ? marks[i + 1].index : body.length;
    sections.push({ title: mark.title, level: mark.level, text: htmlToText(body.slice(mark.end, end)) });
  });

  return sections;
}

// ---------------------------------------------------------------------------
// Wikitext: template-aware parameter extraction (needed for {{Ruby|…}})
// ---------------------------------------------------------------------------

function findBalanced(text: string, start: number): number {
  let depth = 0;
  for (let i = start; i < text.length - 1; i++) {
    if (text[i] === "{" && text[i + 1] === "{") {
      depth++;
      i++;
    } else if (text[i] === "}" && text[i + 1] === "}") {
      depth--;
      i++;
      if (depth === 0) return i + 1;
    }
  }
  return -1;
}

function templateBlock(wikitext: string, name: string): string | null {
  const start = wikitext.indexOf(`{{${name}`);
  if (start < 0) return null;
  const end = findBalanced(wikitext, start);
  return end > 0 ? wikitext.slice(start, end) : null;
}

/** Reads `| key = value` inside a template, tolerating nested {{…}} in the value. */
function readParam(block: string, key: string): string | undefined {
  const re = new RegExp(`\\|\\s*${key}\\s*=`, "i");
  const m = re.exec(block);
  if (!m) return undefined;

  let i = m.index + m[0].length;
  let depth = 0;
  let value = "";
  while (i < block.length) {
    const two = block.slice(i, i + 2);
    if (two === "{{" || two === "[[") {
      depth++;
      value += two;
      i += 2;
      continue;
    }
    if (two === "}}" || two === "]]") {
      depth = Math.max(0, depth - 1);
      value += two;
      i += 2;
      continue;
    }
    const ch = block[i];
    if (depth === 0 && ch === "|") break;
    if (depth === 0 && ch === "\n") {
      // Continue only if the next non-space line does not start a new parameter.
      const rest = block.slice(i + 1);
      if (/^\s*(\||\}\})/.test(rest)) break;
    }
    value += ch;
    i++;
  }
  const cleaned = resolveTemplates(value).replace(/'''?/g, "").replace(/\[\[([^\]|]*\|)?([^\]]+)\]\]/g, "$2").trim();
  return cleaned.split("\n")[0].trim() || undefined;
}

/** Same as readParam but keeps newlines (card lore can span lines). */
function readParamMultiline(block: string, key: string): string | undefined {
  const re = new RegExp(`\\|\\s*${key}\\s*=`, "i");
  const m = re.exec(block);
  if (!m) return undefined;

  let i = m.index + m[0].length;
  let depth = 0;
  let value = "";
  while (i < block.length) {
    const two = block.slice(i, i + 2);
    if (two === "{{" || two === "[[") {
      depth++;
      value += two;
      i += 2;
      continue;
    }
    if (two === "}}" || two === "]]") {
      depth = Math.max(0, depth - 1);
      value += two;
      i += 2;
      continue;
    }
    const ch = block[i];
    if (depth === 0 && ch === "|") break;
    if (depth === 0 && ch === "\n") {
      const rest = block.slice(i + 1);
      if (/^\s*(\||\}\}|<!--)/.test(rest)) break;
    }
    value += ch;
    i++;
  }
  const cleaned = resolveTemplates(value)
    .replace(/'''?/g, "")
    .replace(/\[\[([^\]|]*\|)?([^\]]+)\]\]/g, "$2")
    .replace(/<br\s*\/?>/gi, "\n")
    .replace(/<[^>]+>/g, "")
    .replace(/[ \t]*\n[ \t]*/g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .replace(/[ \t]{2,}/g, " ")
    .trim();
  return cleaned || undefined;
}

function resolveTemplates(input: string): string {
  let text = input;
  for (let pass = 0; pass < 10; pass++) {
    const before = text;
    text = text.replace(/\{\{([^{}]*)\}\}/g, (_match, inner: string) => {
      const parts = inner.split("|");
      const name = parts[0].trim().toLowerCase();
      const positional = parts.slice(1).filter((p) => !/^\s*[a-z0-9_-]+\s*=/i.test(p));

      if (name === "ruby") return (parts[1] || "").trim();
      if (name === "sic" || name === "card" || name === "card name") return (parts[1] || "").trim();
      if (name === "lang") return positional.slice(1).join(" ").trim() || (parts[1] || "").trim();
      if (name === "nbsp" || name === "space") return " ";

      const readable = positional
        .map((p) => p.trim())
        .filter((p) => p.length > 1 && !/^[a-z0-9_:-]+$/i.test(p) && !/^https?:/i.test(p))
        .sort((a, b) => b.length - a.length)[0];
      return readable || "";
    });
    if (text === before) break;
  }
  return text;
}

function parseCardFields(wikitext: string) {
  const block = templateBlock(wikitext, "CardTable2") || wikitext;
  const names: Record<string, string> = {};
  const nameKeys: Record<string, string> = {
    en_name: "en",
    ja_name: "ja",
    romaji_name: "romaji",
    translated_name: "translated",
    fr_name: "fr",
    de_name: "de",
    it_name: "it",
    pt_name: "pt",
    es_name: "es",
    ko_name: "ko",
    ko_rr_name: "ko_rr",
    sc_name: "sc",
    tc_name: "tc",
    ae_name: "ae"
  };
  for (const [key, lang] of Object.entries(nameKeys)) {
    const value = readParam(block, key);
    if (value) names[lang] = value;
  }

  const archRaw = readParam(block, "archseries");
  const archetypes = archRaw ? archRaw.split(/[,;]/).map((s) => s.trim()).filter(Boolean) : [];

  // Card text (effect / flavour) lives in `text`, with localized variants.
  const textKeys: Record<string, string> = {
    text: "en",
    ja_text: "ja",
    translated_text: "translated",
    fr_text: "fr",
    de_text: "de",
    it_text: "it",
    pt_text: "pt",
    es_text: "es",
    ko_text: "ko",
    sc_text: "sc",
    tc_text: "tc"
  };
  const texts: Record<string, string> = {};
  for (const [key, lang] of Object.entries(textKeys)) {
    const value = readParamMultiline(block, key);
    if (value) texts[lang] = value;
  }

  const numeric = (v?: string) => {
    if (!v) return undefined;
    const n = Number(v.replace(/[^\d-]/g, ""));
    return Number.isFinite(n) ? n : undefined;
  };

  return {
    identifiers: {
      passcode: numeric(readParam(block, "password")),
      databaseId: readParam(block, "database_id")
    },
    names,
    lore: texts.en,
    texts,
    stats: {
      attribute: readParam(block, "attribute"),
      types: readParam(block, "types") || readParam(block, "type"),
      level: readParam(block, "level"),
      rank: readParam(block, "rank"),
      linkArrows: readParam(block, "link_arrows"),
      atk: readParam(block, "atk"),
      def: readParam(block, "def"),
      pendulumScale: readParam(block, "pendulum_scale"),
      property: readParam(block, "property"),
      cardType: readParam(block, "card_type")
    },
    archetypes
  };
}

export function extractImages(html: string, limit = 200): string[] {
  const found: string[] = [];
  for (const m of html.matchAll(/title="(File:[^"]+)"/g)) {
    const name = m[1].replace(/^File:/, "").trim();
    if (!name || found.includes(name)) continue;
    found.push(name);
    if (found.length >= limit) break;
  }
  if (found.length === 0) {
    for (const m of html.matchAll(/<img[^>]+src="([^"]+)"/gi)) {
      const src = m[1];
      if (!/yugipedia|wikia/i.test(src)) continue;
      const name = decodeURIComponent(src.split("/").pop() || "");
      if (!name || found.includes(name)) continue;
      found.push(name);
      if (found.length >= limit) break;
    }
  }
  return found;
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

async function fetchPage(title: string, refresh = false): Promise<CachedPage | null> {
  if (!refresh) {
    const cached = readCache(title);
    if (cached) return cached;
  }

  const data = await callApi({
    action: "parse",
    page: title,
    prop: "text|sections|wikitext|displaytitle",
    redirects: "1",
    disablelimitreport: "1",
    disableeditsection: "1"
  });

  if (data?.error) return null;
  const page: CachedPage = {
    title: data.parse.title as string,
    html: (data.parse.text as string) || "",
    wikitext: ((data.parse.wikitext as string) || "").replace(/<!--[\s\S]*?-->/g, ""),
    sections: ((data.parse.sections as any[]) || []).map((s) => ({ index: String(s.index), line: String(s.line), level: String(s.level) })),
    fetchedAt: new Date().toISOString()
  };
  // Extract images once; gallery pages are large and re-parsing them per call is wasteful.
  try {
    page.images = extractImages(stripWikiChrome(page.html));
  } catch {
    page.images = [];
  }
  if (!page.html && !page.wikitext) return null;

  writeCache(page);
  if (page.title !== title) writeCache({ ...page, title });
  return page;
}

/** Resolves a card name, passcode, database ID, set code or archetype name. */
export async function resolveTitle(input: string): Promise<{ title: string; redirected: boolean } | null> {
  const trimmed = input.trim();
  if (!trimmed) return null;

  const data = await callApi({
    action: "query",
    prop: "info",
    titles: trimmed,
    redirects: "1"
  });
  const first = ((data?.query?.pages || []) as any[])[0];
  if (first && !first.missing) return { title: first.title, redirected: Boolean(data?.query?.redirects?.length) };

  const search = await searchWiki(trimmed, 5);
  if (search.length > 0) return { title: search[0].title, redirected: true };
  return null;
}

export async function searchWiki(query: string, limit = 10): Promise<Array<{ title: string; snippet: string; namespace: number }>> {
  const data = await callApi({
    action: "query",
    list: "search",
    srsearch: query,
    srlimit: String(Math.min(limit, 20)),
    srprop: "snippet"
  });
  return ((data?.query?.search || []) as any[]).map((item) => ({
    title: item.title,
    snippet: String(item.snippet || "").replace(/<[^>]+>/g, "").replace(/\s+/g, " ").trim(),
    namespace: item.ns
  }));
}

/** Which tabs (Gallery/Rulings/…) exist for a card. */
export async function getCardTabs(page: string): Promise<Record<string, boolean>> {
  const titles = Object.values(CARD_TABS).map((ns) => `${ns}:${page}`);
  const data = await callApi({
    action: "query",
    prop: "info",
    titles: titles.join("|"),
    redirects: "1"
  });
  const pages = (data?.query?.pages || []) as any[];
  const result: Record<string, boolean> = {};
  for (const [key, ns] of Object.entries(CARD_TABS)) {
    const target = `${ns}:${page}`.toLowerCase();
    const match = pages.find((p) => String(p.title).toLowerCase() === target);
    result[key] = Boolean(match && !match.missing);
  }
  return result;
}

const pageUrl = (title: string) => `https://yugipedia.com/wiki/${encodeURIComponent(title.replace(/ /g, "_"))}`;

export interface WikiCardResult {
  available: boolean;
  page?: string;
  url?: string;
  identifiers?: { passcode?: number; databaseId?: string };
  names?: Record<string, string>;
  lore?: string;
  texts?: Record<string, string>;
  stats?: Record<string, string | number | undefined>;
  archetypes?: string[];
  tabs?: Record<string, boolean>;
  sections?: string[];
  section?: string;
  text?: string;
  images?: string[];
  license?: string;
  reason?: string;
}

export async function getCard(input: string, options: { refresh?: boolean; section?: string } = {}): Promise<WikiCardResult> {
  const resolved = await resolveTitle(input);
  if (!resolved) return { available: false, reason: `No Yugipedia page found for "${input}".` };

  const page = await fetchPage(resolved.title, options.refresh);
  if (!page) return { available: false, reason: `Yugipedia has no content for "${resolved.title}".` };

  const fields = parseCardFields(page.wikitext);
  const names = { ...fields.names };
  if (!names.en && fields.identifiers.passcode) names.en = page.title;
  const rendered = splitHtmlSections(page.html);
  const tabs = await getCardTabs(page.title).catch(() => ({} as Record<string, boolean>));

  const base: WikiCardResult = {
    available: true,
    page: page.title,
    url: pageUrl(page.title),
    identifiers: fields.identifiers,
    names,
    lore: fields.lore,
    texts: fields.texts,
    stats: fields.stats,
    archetypes: fields.archetypes,
    tabs,
    sections: rendered.map((s) => s.title),
    license: YUGIPEDIA_LICENSE
  };

  if (options.section) {
    const needle = options.section.trim().toLowerCase();
    const found = rendered.find((s) => s.title.toLowerCase() === needle) || rendered.find((s) => s.title.toLowerCase().includes(needle));
    if (!found) {
      return { ...base, available: false, reason: `No section "${options.section}". Available: ${rendered.map((s) => s.title).join(", ")}` };
    }
    return { ...base, section: found.title, text: found.text.slice(0, MAX_TEXT) };
  }

  const lead = rendered.find((s) => s.title === "Lead")?.text || rendered[0]?.text || "";
  return { ...base, text: fields.lore || lead.slice(0, MAX_TEXT) };
}

/** Reads a card tab page: rulings / tips / trivia / gallery / errata / artworks / … */
export async function getCardTab(
  input: string,
  tab: CardTab,
  options: { refresh?: boolean; imagesOnly?: boolean } = {}
): Promise<{
  available: boolean;
  page?: string;
  tab?: string;
  url?: string;
  sections?: string[];
  text?: string;
  images?: string[];
  imageCount?: number;
  license?: string;
  reason?: string;
}> {
  const resolved = await resolveTitle(input);
  if (!resolved) return { available: false, reason: `Card "${input}" was not found.` };

  const namespace = CARD_TABS[tab];
  if (!namespace) {
    return { available: false, reason: `Invalid tab. Choose: ${Object.keys(CARD_TABS).join(", ")}` };
  }

  const title = `${namespace}:${resolved.title}`;
  const page = await fetchPage(title, options.refresh);
  if (!page) {
    return {
      available: false,
      page: resolved.title,
      tab,
      reason: `Card "${resolved.title}" has no ${namespace} page on Yugipedia.`
    };
  }

  const cleaned = stripWikiChrome(page.html);
  const images = page.images?.length ? page.images : extractImages(cleaned);
  const rendered = splitHtmlSections(cleaned);
  // The "Lead" of a card tab is the tab bar + navboxes, never real content.
  const content = rendered.filter((s) => s.title !== "Lead" && s.text.trim().length > 0);
  const chosen = content.length > 0 ? content : rendered;
  const text = options.imagesOnly
    ? undefined
    : chosen
        .map((s) => `${s.title === "Lead" ? "Content" : s.title}\n${s.text}`)
        .join("\n\n")
        .slice(0, MAX_TEXT);

  return {
    available: true,
    page: resolved.title,
    tab,
    url: pageUrl(title),
    sections: rendered.map((s) => s.title),
    text: text || undefined,
    images: images.length ? images : undefined,
    imageCount: images.length || undefined,
    license: YUGIPEDIA_LICENSE
  };
}

/** Generic page reader: sets, products, archetypes, anything on the wiki. */
export async function getWikiPage(
  title: string,
  options: { refresh?: boolean; section?: string; images?: boolean } = {}
): Promise<{
  available: boolean;
  page?: string;
  url?: string;
  sections?: string[];
  section?: string;
  text?: string;
  images?: string[];
  license?: string;
  reason?: string;
}> {
  const page = await fetchPage(title, options.refresh);
  if (!page) return { available: false, reason: `No page "${title}" on Yugipedia.` };

  const rendered = splitHtmlSections(page.html);
  const base = {
    available: true,
    page: page.title,
    url: pageUrl(page.title),
    sections: rendered.map((s) => s.title),
    license: YUGIPEDIA_LICENSE
  };

  if (options.section) {
    const needle = options.section.trim().toLowerCase();
    const found = rendered.find((s) => s.title.toLowerCase() === needle) || rendered.find((s) => s.title.toLowerCase().includes(needle));
    if (!found) {
      return { ...base, available: false, reason: `No section "${options.section}". Available: ${rendered.map((s) => s.title).join(", ")}` };
    }
    return {
      ...base,
      section: found.title,
      text: found.text.slice(0, MAX_TEXT),
      images: options.images ? extractImages(found.text ? page.html : "", 50) : undefined
    };
  }

  const lead = rendered.find((s) => s.title === "Lead")?.text || "";
  return {
    ...base,
    text: lead.slice(0, MAX_TEXT),
    images: options.images ? extractImages(page.html, 50) : undefined
  };
}

export function getWikiStatus(): {
  cacheDir: string;
  cachedPages: number;
  license: string;
  source: string;
  ttlDays: number;
} {
  let cachedPages = 0;
  try {
    cachedPages = fs.readdirSync(PAGE_CACHE).filter((f) => f.endsWith(".json")).length;
  } catch {
    cachedPages = 0;
  }
  return {
    cacheDir: CACHE_DIR,
    cachedPages,
    license: YUGIPEDIA_LICENSE,
    source: API,
    ttlDays: Math.round(TTL_MS / 86_400_000)
  };
}
